add_shortcode( '{{stock_shortcode_name}}', 'perfectpixel_stock_quantity_shortcode' );

function perfectpixel_stock_quantity_shortcode( $atts ) {
	$atts    = shortcode_atts( array( 'id' => 0 ), $atts );
	$product = wc_get_product( absint( $atts['id'] ) ? absint( $atts['id'] ) : get_the_ID() );
	if ( ! $product ) {
		return '';
	}
	if ( $product->managing_stock() ) {
		return '<span class="perfectpixel-stock-qty">' . esc_html( wc_stock_amount( max( 0, (int) $product->get_stock_quantity() ) ) ) . '</span>';
	}
	return '<span class="perfectpixel-stock-qty">' . esc_html( $product->is_in_stock() ? __( 'In stock', 'woocommerce' ) : __( 'Out of stock', 'woocommerce' ) ) . '</span>';
}
